<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {RefreshCw,Search,ClipboardList} from 'lucide-vue-next'
import {request,json,type Actor} from '../api'
const props=defineProps<{actors:Actor[]}>()
const emit=defineEmits<{actor:[name:string];work:[work:any]}>()
const plan=ref<any>({actors:[],items:[],summary:{}}),loading=ref(false),error=ref(''),notice=ref(''),syncing=ref(''),changing=ref(''),search=ref(''),actorFilter=ref(''),statusFilter=ref('planned'),source=ref('javdbui'),syncPages=ref(5),page=ref(1)
let generation=0
const labels:Record<string,string>={complete:'尽量收全',selective:'精选收藏',planned:'待收集',queued:'已提交下载',ignored:'已暂缓'}
const filtered=computed(()=>plan.value.items.filter((item:any)=>(!actorFilter.value||item.actors.includes(actorFilter.value))&&(!statusFilter.value||item.status===statusFilter.value)&&(!search.value||[item.code,item.title,...item.actors].join(' ').toLowerCase().includes(search.value.toLowerCase()))))
const pageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/30)))
const visibleItems=computed(()=>filtered.value.slice((page.value-1)*30,page.value*30))
watch([search,actorFilter,statusFilter],()=>page.value=1)
watch(()=>filtered.value.length,()=>{page.value=Math.min(page.value,pageCount.value)})
async function load(){const id=++generation;loading.value=true;error.value='';try{const data=await request<any>('/collection-plan');if(id===generation)plan.value=data}catch(e:any){if(id===generation)error.value=e.message||String(e)}finally{if(id===generation)loading.value=false}}
async function syncActor(name:string){if(syncing.value)return;syncing.value=name;error.value='';notice.value='';try{const result=await request<any>('/catalog/sync',json('POST',{actor:name,source:source.value,pages:syncPages.value}));notice.value=`${name}：已读取 ${result.count||0} 项目录${result.complete?'':'，目录尚未完整'}`}catch(e:any){error.value=syncErrorText(e.message||String(e))}finally{syncing.value='';await loadPreservingError()}}
async function loadPreservingError(){const previous=error.value;await load();if(previous)error.value=previous}
async function setStatus(item:any,status:string){changing.value=item.id;error.value='';try{await request(`/collection-plan/${encodeURIComponent(item.id)}`,json('PATCH',{status}));await load()}catch(e:any){error.value=e.message||String(e)}finally{changing.value=''}}
async function enrichItem(item:any){if(changing.value||!item.catalog_id)return;changing.value=item.id;error.value='';try{await request(`/catalog/${encodeURIComponent(item.catalog_id)}/enrich`,json('POST',{}));await load();notice.value=`${item.code} 的来源资料已更新`}catch(e:any){error.value=e.message||String(e)}finally{changing.value=''}}
function safeURL(raw:string){try{const u=new URL(raw);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}}
function syncErrorText(message:string){return message.replace('JavDB actor page requires browser verification','JavDB 要求浏览器验证，目录尚未同步').replace('JavDB actor page blocked the request','JavDB 拒绝目录请求').replace('no exact actor match','没有精确匹配的演员')}
function statusLabel(item:any){return item.candidate_status==='uncertain'?'下载结果待确认':item.candidate_status==='submitting'?'正在提交下载':labels[item.status]}
function resourceURL(code:string){return code?'https://sukebei.nyaa.si/?q='+encodeURIComponent(code):''}
watch(()=>JSON.stringify(props.actors.map(a=>[a.name,a.policy,a.target])),()=>void load())
defineExpose({load})
onMounted(load)
</script>
<template><section class="collection-plan-page">
 <div class="page-heading"><div><h1>收集计划</h1><p>根据演员策略列出已知缺口，下载和入库由你确认。</p></div><button class="btn secondary" :disabled="loading" @click="load"><RefreshCw/>{{loading?'正在读取…':'刷新计划'}}</button></div>
 <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="plan-notice" role="status">{{notice}}</p>
 <div class="stat-grid"><div class="stat-card"><div class="stat-top">计划演员 <ClipboardList/></div><strong>{{plan.summary.actors||0}}</strong><small>尽量收全 / 精选收藏</small></div><div class="stat-card"><div class="stat-top">待收集</div><strong>{{plan.summary.planned||0}}</strong><small>按编号合并多人作品</small></div><div class="stat-card"><div class="stat-top">已提交下载</div><strong>{{plan.summary.queued||0}}</strong><small>按已记录的候选状态判断</small></div><div class="stat-card"><div class="stat-top">已暂缓</div><strong>{{plan.summary.ignored||0}}</strong><small>可随时恢复到计划</small></div></div>
 <details class="plan-help"><summary>收集策略如何形成计划？</summary><p>尽量收全：将已同步目录中尚未拥有的普通作品列入计划，合集不自动列入。精选收藏：优先按来源评分选择作品，补足设定的目标数量；评分缺失时会明确标注。只关注：不自动加入计划。</p><p>更改策略会重新计算计划，不会自动下载。先同步演员目录，再查找资源并手动提交下载；扫描入库后，已有作品会自动离开计划。设备离线不影响已登记作品的拥有状态。</p></details>
 <div class="section-head"><div><h2>演员目标</h2><p>目录可能不完整；“目录已知”不代表演员的全部作品。</p></div><div class="plan-sync-controls"><label class="plan-source">同步来源<select v-model="source" aria-label="收集计划同步来源"><option value="javdbui">JavDB UI</option><option value="javdb">JavDB</option><option value="javlibrary">JavLibrary</option><option value="fanza">FANZA</option><option value="javbus">JavBus</option></select></label><label v-if="source==='javdbui'" class="plan-source">单次范围<select v-model.number="syncPages" aria-label="目录同步页数"><option :value="5">最多 5 页</option><option :value="10">最多 10 页</option><option :value="20">最多 20 页</option><option :value="50">最多 50 页</option></select></label></div></div>
 <div v-if="loading&&!plan.actors.length" class="empty-inline" role="status">正在读取收集计划…</div>
 <div v-else-if="!plan.actors.length" class="empty-inline">还没有收集目标。在演员收藏中选择“尽量收全”或“精选收藏”，即可生成计划。</div>
 <div v-else class="table-wrap"><table><thead><tr><th>演员</th><th>策略</th><th>本地拥有</th><th>目录已知</th><th>待收集</th><th>目录状态</th><th>操作</th></tr></thead><tbody><tr v-for="actor in plan.actors" :key="actor.name"><td><button class="text-btn" @click="emit('actor',actor.name)">{{actor.name}}</button></td><td>{{labels[actor.policy]}}<small v-if="actor.policy==='selective'"> · 目标 {{actor.target}} 部</small></td><td>{{actor.owned}}<small class="plan-sync-date">目录匹配 {{actor.known_owned||0}} 部</small></td><td>{{actor.known}}</td><td>{{actor.planned}}</td><td><span :class="{'plan-warning':actor.needs_sync}">{{actor.needs_sync?'待同步 / 目录不完整':'最近同步完成'}}</span><small class="plan-sync-date" v-if="actor.last_synced_at">{{new Date(actor.last_synced_at).toLocaleString()}}</small><small v-if="actor.last_sync_error" class="plan-sync-error">{{syncErrorText(actor.last_sync_error)}}</small></td><td><button class="btn secondary" :disabled="!!syncing" @click="syncActor(actor.name)">{{syncing===actor.name?'正在同步…':'同步目录'}}</button></td></tr></tbody></table></div>
 <div class="section-head plan-list-heading"><div><h2>计划作品 <span class="muted">{{filtered.length}}</span></h2><p>同一作品可满足多位演员的目标，只显示一条记录。</p></div></div>
 <div class="plan-filters"><label class="global-search local"><Search/><input v-model="search" placeholder="搜索计划中的编号、标题或演员"/></label><select v-model="actorFilter" aria-label="计划演员筛选"><option value="">所有计划演员</option><option v-for="actor in plan.actors" :key="actor.name" :value="actor.name">{{actor.name}}</option></select><select v-model="statusFilter" aria-label="计划状态"><option value="planned">待收集</option><option value="queued">已提交下载</option><option value="ignored">已暂缓</option><option value="">全部状态</option></select></div>
 <div v-if="!filtered.length&&!loading" class="empty-inline">{{plan.actors.some((actor:any)=>actor.needs_sync)?'当前筛选下没有计划作品。请先同步演员目录，获取更多已知作品。':'当前筛选下没有待处理的计划作品。'}}</div>
 <div v-else class="plan-work-list"><article v-for="item in visibleItems" :key="item.id" class="plan-work"><div class="plan-work-main"><div class="plan-work-meta"><b>{{item.code}}</b><span>{{item.year||'年份未知'}}</span><span>{{statusLabel(item)}}</span><span>{{item.rating!=null?'来源评分 '+item.rating+' / 5':'来源评分待补充'}}</span></div><h3><button class="plan-work-title" @click="emit('work',{...item,id:'plan:'+item.id,actors:item.actors,tags:[],source_url:item.source_url})">{{item.title||item.code}}</button></h3><p>{{item.actors.join('、')}}</p><ul><li v-for="reason in item.reasons" :key="reason">{{reason}}</li></ul></div><div class="plan-work-actions"><button v-if="item.catalog_id" class="btn secondary" :disabled="!!changing" @click="enrichItem(item)">{{changing===item.id?'正在处理…':'更新评分资料'}}</button><a v-if="safeURL(item.source_url)" class="btn secondary" :href="safeURL(item.source_url)" target="_blank" rel="noopener noreferrer">作品来源 ↗</a><a v-if="resourceURL(item.code)" class="btn secondary" :href="resourceURL(item.code)" target="_blank" rel="noopener noreferrer">查找资源 ↗</a><button class="text-btn" :disabled="!!changing||item.status==='queued'" @click="setStatus(item,item.status==='ignored'?'planned':'ignored')">{{item.status==='ignored'?'恢复计划':'暂缓收集'}}</button></div></article></div>
 <div v-if="filtered.length>30" class="torrent-pagination"><span>第 {{page}} / {{pageCount}} 页</span><button class="btn secondary" :disabled="page<=1" @click="page--">上一页</button><button class="btn secondary" :disabled="page>=pageCount" @click="page++">下一页</button></div>
</section></template>
<style scoped>
.collection-plan-page .text-btn{border:0;background:none;padding:6px 0;color:#327d88;font:inherit;cursor:pointer;text-align:left}.collection-plan-page .text-btn:disabled{opacity:.5;cursor:default}.plan-filters select,.plan-source select{height:40px;padding:7px 12px;border:1px solid var(--line);border-radius:6px;background:white;color:#44535a;font:inherit;font-size:14px}.plan-filters .global-search input{display:block;min-width:0}.plan-filters .global-search{padding:0 12px;border:1px solid var(--line);background:white;height:40px}

.plan-help{background:var(--surface,#fff);border:1px solid var(--border,#dde4e7);border-radius:10px;padding:18px 20px;margin:22px 0 28px;line-height:1.8}.plan-help summary{cursor:pointer;font-weight:600}.plan-help p{margin:12px 0 0;color:var(--text-muted,#647780)}.plan-sync-controls{display:flex;gap:14px;flex-wrap:wrap;justify-content:flex-end}.plan-source{display:flex;align-items:center;gap:12px;white-space:nowrap}.plan-source select{min-width:140px}.plan-notice{padding:12px 16px;background:#edf6f2;border-radius:8px;color:#326951}.plan-filters{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.plan-filters .global-search{flex:1;min-width:240px}.plan-list-heading{margin-top:32px}.plan-warning{color:#8e6824}.plan-sync-error{display:block;color:#98694e;max-width:280px;line-height:1.6;margin-top:6px;font-size:13px;overflow-wrap:anywhere}.plan-sync-date{display:block;color:#7b8a92;margin-top:5px;font-size:13px}.plan-work-list{display:grid;gap:12px}.plan-work{background:#fff;border:1px solid var(--border,#dde4e7);border-radius:10px;padding:22px 24px;display:flex;justify-content:space-between;gap:24px}.plan-work-main{min-width:0}.plan-work-meta{display:flex;flex-wrap:wrap;gap:14px;align-items:center;color:#72838b;font-size:14px}.plan-work-meta b{color:#3d858e}.plan-work h3{margin:12px 0 8px;font-size:18px;line-height:1.65}.plan-work-title{all:unset;cursor:pointer;overflow-wrap:anywhere}.plan-work p{margin:0 0 10px;color:#637780}.plan-work ul{padding-left:18px;margin:0;color:#7b8a92;font-size:14px;line-height:1.7}.plan-work-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;justify-content:flex-end;align-content:center;min-width:230px}.plan-work-actions .btn{white-space:nowrap}@media(max-width:800px){.plan-work{flex-direction:column;padding:18px}.plan-work-actions{justify-content:flex-start}.plan-source{flex-wrap:wrap}.stat-grid{grid-template-columns:repeat(2,1fr)}}
</style>
